                 .defaultIfEmpty(snapshot)
                 .map(baseSnapshot -> determineRawAndContentPatch(snapshot, baseSnapshot, contentRequest))
                 .flatMap(source -> getContextUsername()
-                        .doOnNext(username -> {
+                        .map(username -> {
                             Snapshot.addContributor(source, username);
                             source.getSpec().setOwner(username);
-                        })
-                        .thenReturn(source))
+                            return source;
+                        }))
                 .flatMap(client::create);
     }

@@ -119,8 +119,10 @@ public abstract class AbstractContentService {
                                 .map(baseSnapshot ->
                                         determineRawAndContentPatch(headSnapshot, baseSnapshot, contentRequest)))
                         .flatMap(headSnapshot -> getContextUsername()
-                                .doOnNext(username -> Snapshot.addContributor(headSnapshot, username))
-                                .thenReturn(headSnapshot))
+                                .map(username -> {
+                                    Snapshot.addContributor(headSnapshot, username);
+                                    return headSnapshot;
+                                }))
                         .flatMap(client::update))
                 .retryWhen(Retry.backoff(5, Duration.ofMillis(100))
                         .filter(throwable -> throwable instanceof OptimisticLockingFailureException))
